export interface ExamQuestion {
  id: string;
  questionNumber: number;
  type: 'listening' | 'grammar' | 'cloze' | 'reading' | string;
  categoryTag: string;
  title: string;
  questionText: string;
  passage?: string;
  audioScript?: string;
  options: { key: string; text: string }[];
  correctAnswer: string;
  score: number;
  explanation: string;
  explanationDetail?: {
    analysis: string;
    vocabList: { word: string; meaning: string }[];
    translation: string;
  };
}

export interface ExamPaper {
  id: string;
  title: string;
  spanishTitle?: string;
  mode: MainExamMode;
  track: ExamTrack;
  level: string;
  category: string;
  schoolOrOrg: string;
  yearSession: string;
  durationMinutes: number;
  totalScore: number;
  totalQuestions: number;
  isFreePreview: boolean;
  summary: string;
  questions: ExamQuestion[];
}

